// ============================================================================
//  make-train-mesh — js/CollapseTrainMesh.js from art_src/train_v3/train_manifest_v3.json
// ----------------------------------------------------------------------------
//  The manifest owns the train's unfolding (every face in art px, UV, normals, triangles) and does not
//  go into the build; the game draws the same faces from this generated file, merged per texture.
//  node tools/art/make-train-mesh.mjs           rewrite the file
//  node tools/art/make-train-mesh.mjs --check   exit 1 if the file differs from the manifest
// ============================================================================
import fs from 'node:fs';
import path from 'node:path';
import url from 'node:url';

const ROOT = path.resolve(path.dirname(url.fileURLToPath(import.meta.url)), '..', '..');
export const OUT = path.join(ROOT, 'js', 'CollapseTrainMesh.js');
const DIR = 'assets/textures/train/';

export function readManifest() {
  return JSON.parse(fs.readFileSync(path.join(ROOT, 'art_src/train_v3/train_manifest_v3.json'), 'utf8'));
}

// Faces of one texture and one role go into one draw call. Texture V is flipped here: the manifest
// counts from the top of the PNG, Babylon's invertY textures from the bottom.
export function groupFaces(man) {
  const groups = new Map();
  for (const f of man.faces) {
    const side = f.part === 'running' ? (f.phase_offset ? 'left' : 'right') : '';
    const key = [f.texture, f.part === 'running' ? side : '', f.part === 'emission' || f.part === 'damage_decal' ? f.part : ''].join('|');
    let g = groups.get(key);
    if (!g) {
      g = { tex: DIR + f.texture, part: f.part, solid: !!f.solid, phase: f.phase_offset || 0, pos: [], uv: [], nor: [], idx: [] };
      if (f.texture_sequence) g.frames = f.texture_sequence.map(t => DIR + t);
      groups.set(key, g);
    }
    const base = g.pos.length / 3;
    f.vertices_px.forEach((v, k) => {
      g.pos.push(...v);
      g.uv.push(f.uv_top_left[k][0], Math.round((1 - f.uv_top_left[k][1]) * 1e4) / 1e4);
      g.nor.push(...f.normal);
    });
    for (const t of f.triangles) g.idx.push(base + t[0], base + t[1], base + t[2]);
  }
  return [...groups.values()];
}

export function render(man) {
  const unit = 80, pivot = man.coordinate_system.train_pivot_units[2] * unit;
  const broken = man.states.broken.replace;
  const lines = groupFaces(man).map(g => '    ' + JSON.stringify(g));
  const replace = Object.entries(broken).map(([a, b]) => `        '${DIR}${a}': '${DIR}${b}',`);
  const box = id => {
    const vs = man.faces.filter(f => f.part === id).flatMap(f => f.vertices_px);
    return [0, 1, 2].map(k => [Math.min(...vs.map(v => v[k])), Math.max(...vs.map(v => v[k]))]);
  };
  const chimney = box('chimney'), all = man.faces.flatMap(f => f.vertices_px);
  return `// CollapseTrainMesh.js — GENERATED by tools/art/make-train-mesh.mjs from art_src/train_v3/train_manifest_v3.json.
// Do not edit. Art px: x to the engine's right, y up, z from the nose to the tender; winding CCW outside.

/** @satisfies {Record<string, any>} */
const CollapseTrainMesh = {
    PIVOT_PX: ${pivot},      // the yaw pivot on the center line, px behind the nose
    HALF_WIDTH_PX: ${Math.max(...all.map(v => Math.abs(v[0])))},
    TOP_PX: ${Math.max(...all.map(v => v[1]))},
    CHIMNEY_PX: [${(chimney[0][0] + chimney[0][1]) / 2}, ${chimney[1][1]}, ${(chimney[2][0] + chimney[2][1]) / 2}],   // the middle of its top
    WHEEL_R_PX: ${man.animation.running.wheel_radius_px},
    WHEEL_PHASES: ${man.animation.running.frames},
    BROKEN: {
${replace.join('\n')}
    },
    GROUPS: [
${lines.join(',\n')},
    ],
};
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === url.fileURLToPath(import.meta.url)) {
  const text = render(readManifest());
  if (process.argv.includes('--check')) {
    const same = fs.existsSync(OUT) && fs.readFileSync(OUT, 'utf8') === text;
    console.log(same ? 'совпадает с манифестом' : 'js/CollapseTrainMesh.js не совпадает с манифестом');
    process.exitCode = same ? 0 : 1;
  } else {
    fs.writeFileSync(OUT, text);
    console.log('записан js/CollapseTrainMesh.js, ' + text.length + ' байт');
  }
}
